package com.hellodoc.service;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.hellodoc.dto.*; import com.hellodoc.entity.*; import com.hellodoc.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service public class DoctorProfileService {
 private final DoctorRepository doctors; private final AvailabilityRepository availabilities; private final AbsenceRepository absences; private final AppointmentRepository appointments; private final SpecialtyService specialties; private final PasswordEncoder passwords; private final ObjectMapper json;
 @Value("${hellodoc.booking.min-notice-minutes:60}") private long minimumNoticeMinutes=60;
 @Value("${hellodoc.booking.max-horizon-days:60}") private long maximumHorizonDays=60;
 public DoctorProfileService(DoctorRepository doctors,AvailabilityRepository availabilities,AbsenceRepository absences,AppointmentRepository appointments,SpecialtyService specialties,PasswordEncoder passwords,ObjectMapper json){this.doctors=doctors;this.availabilities=availabilities;this.absences=absences;this.appointments=appointments;this.specialties=specialties;this.passwords=passwords;this.json=json;}
 @Transactional(readOnly=true) public DoctorProfileDto ownProfile(String email){Doctor d=own(email);var av=availabilities.findByDoctorIdOrderByIsoWeekdayAscStartTimeAsc(d.getId());return DoctorProfileDto.from(d,av.stream().map(Availability::getIsoWeekday).distinct().toList(),av.stream().map(Availability::getStartTime).min(LocalTime::compareTo).map(LocalTime::toString).orElse(null),av.stream().map(Availability::getEndTime).max(LocalTime::compareTo).map(LocalTime::toString).orElse(null),services(d));}
 @Transactional public DoctorProfileDto update(String email,DoctorProfileUpdateRequest r){Doctor d=lockOwnSchedule(email);UserAccount u=d.getUser();if(!passwords.matches(r.currentPassword(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Le mot de passe actuel est incorrect.");String servicesJson=writeServices(r.services().stream().map(s->new MedicalServiceDto(s.name(),s.price())).toList());d.updateProfile(r.serviceTitle().trim(),d.getCity(),r.address().trim(),r.location().trim(),r.description()==null?"":r.description().trim(),d.getDurationMinutes(),d.getPauseMinutes(),servicesJson);u.updateContactProfile(r.firstName().trim(),r.lastName().trim(),clean(r.phone()),r.address().trim());d.getSpecialties().clear();d.addSpecialty(specialties.findOrCreate(r.specialty()));return ownProfile(email);}
 @Transactional(readOnly=true) public Page<DoctorSearchDto> search(String q,String specialty,String city,LocalDate availableOn,int page,int size){int p=Math.max(0,page),n=Math.min(Math.max(1,size),100);String qv=blank(q),cv=blank(city),sv=blank(specialty)==null?null:Specialty.normalize(specialty);Page<Doctor> result=doctors.search(qv,cv,sv,PageRequest.of(availableOn==null?p:0,availableOn==null?n:500,Sort.by("serviceTitle").ascending()));if(availableOn==null)return result.map(d->DoctorSearchDto.from(d,nextAvailability(d,LocalDate.now(ZoneId.of("Africa/Tunis")))));List<Doctor> filtered=result.getContent().stream().filter(d->!availableSlots(d,availableOn,ZoneId.of("Africa/Tunis")).isEmpty()).toList();int from=Math.min(p*n,filtered.size()),to=Math.min(from+n,filtered.size());return new PageImpl<>(filtered.subList(from,to).stream().map(d->DoctorSearchDto.from(d,nextAvailability(d,LocalDate.now(ZoneId.of("Africa/Tunis"))))).toList(),PageRequest.of(p,n),filtered.size());}
 @Transactional(readOnly=true) public DoctorPublicDto publicProfile(UUID id){Doctor d=doctors.findByIdAndActiveTrue(id).filter(x->x.getUser().getStatus().equals("ACTIVE")&&x.getUser().getRole()==UserRole.DOCTOR).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profil médecin introuvable."));var av=availabilities.findByDoctorIdOrderByIsoWeekdayAscStartTimeAsc(id);return DoctorPublicDto.from(d,av.stream().map(Availability::getIsoWeekday).distinct().toList(),services(d),nextAvailability(d,LocalDate.now(ZoneId.of("Africa/Tunis"))));}
 @Transactional(readOnly=true) public Map<String,Object> bookingPolicy(UUID id){doctors.findByIdAndActiveTrue(id).filter(d->d.getUser().getStatus().equals("ACTIVE")&&d.getUser().getRole()==UserRole.DOCTOR).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profil médecin introuvable."));ZoneId zone=ZoneId.of("Africa/Tunis");LocalDate today=LocalDate.now(zone);return Map.of("timeZone",zone.getId(),"minDate",today,"maxDate",today.plusDays(maximumHorizonDays),"minimumNoticeMinutes",minimumNoticeMinutes);}
 @Transactional(readOnly=true) public List<TimeSlotDto> slots(UUID id,LocalDate date){Doctor d=doctors.findByIdAndActiveTrue(id).filter(x->x.getUser().getStatus().equals("ACTIVE")&&x.getUser().getRole()==UserRole.DOCTOR).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profil médecin introuvable."));return slots(d,date,ZoneId.of("Africa/Tunis"));}
 @Transactional public Doctor createFromApplication(DoctorApplication a){if(doctors.findByUserEmailIgnoreCase(a.getUser().getEmail()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Un profil médecin existe déjà pour cette candidature.");List<MedicalServiceDto> listed=parseServices(a.getServicesJson(),a.getId());String safeServices=writeServices(listed);int duration=validDuration(a.getDurationMinutes())?a.getDurationMinutes():30;int pause=Math.max(0,Math.min(240,a.getPauseMinutes()));Doctor d=doctors.save(new Doctor(a.getUser(),a,a.getServiceTitle(),a.getCity(),a.getPracticeAddress(),a.getPracticeAddress(),safe(a.getDescription()),duration,pause,safeServices));d.addSpecialty(specialties.findOrCreate(a.getSpecialty()));
  List<Integer> days=parseDays(a);LocalTime start=parseSafeTime(a.getWorkStart()),end=parseSafeTime(a.getWorkEnd()),secondStart=parseSafeTime(a.getSecondWorkStart()),secondEnd=parseSafeTime(a.getSecondWorkEnd());if(days.isEmpty()&&"[]".equals(a.getWorkingDaysJson()))return d;if(days.isEmpty()||start==null||end==null||!end.isAfter(start)||!validDuration(a.getDurationMinutes())){warn(a,"horaires/jours");return d;}for(int day:days)try{availabilities.save(new Availability(d,day,1,start,end,duration,pause));if(secondStart!=null&&secondEnd!=null&&secondStart.isAfter(end)&&secondEnd.isAfter(secondStart))availabilities.save(new Availability(d,day,2,secondStart,secondEnd,duration,pause));else if(a.getSecondWorkStart()!=null||a.getSecondWorkEnd()!=null)System.getLogger(getClass().getName()).log(System.Logger.Level.WARNING,"Candidature médecin "+a.getId()+" : seconde plage invalide, ignorée pour le jour ISO "+day+".");}catch(RuntimeException ex){System.getLogger(getClass().getName()).log(System.Logger.Level.WARNING,"Candidature médecin "+a.getId()+" : disponibilité ISO "+day+" ignorée: "+ex.getMessage());}return d;}
 @Transactional(readOnly=true) public List<AvailabilityDto> listAvailabilities(String email){return availabilities.findByDoctorIdOrderByIsoWeekdayAscStartTimeAsc(own(email).getId()).stream().map(AvailabilityDto::from).toList();}
 @Transactional public AvailabilityDto addAvailability(String email,AvailabilityRequest r){Doctor d=lockOwnSchedule(email);LocalTime start=parseTime(r.startTime()),end=parseTime(r.endTime());validateUnique(d.getId(),null,r.isoWeekday(),start,end);return AvailabilityDto.from(availabilities.save(new Availability(d,r.isoWeekday(),start,end,r.slotDurationMinutes(),r.pauseMinutes())));}
 @Transactional public AvailabilityDto updateAvailability(String email,UUID id,AvailabilityRequest r){Doctor d=lockOwnSchedule(email);Availability a=availabilities.findByIdAndDoctorId(id,d.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Disponibilité introuvable."));LocalTime start=parseTime(r.startTime()),end=parseTime(r.endTime());validateUnique(d.getId(),id,r.isoWeekday(),start,end);a.update(r.isoWeekday(),start,end,r.slotDurationMinutes(),r.pauseMinutes());return AvailabilityDto.from(a);}
 @Transactional public void deleteAvailability(String email,UUID id){Doctor d=lockOwnSchedule(email);Availability a=availabilities.findByIdAndDoctorId(id,d.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Disponibilité introuvable."));availabilities.delete(a);}
 @Transactional(readOnly=true) public Doctor own(String email){return doctors.findByUserEmailIgnoreCase(email).filter(d->d.isActive()&&d.getUser().getStatus().equals("ACTIVE")&&d.getUser().getRole()==UserRole.DOCTOR).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Profil médecin actif requis."));}
 @Transactional public Doctor lockOwnSchedule(String email){Doctor own=own(email);return doctors.lockActiveById(own.getId()).filter(d->d.isActive()&&"ACTIVE".equals(d.getUser().getStatus())&&d.getUser().getRole()==UserRole.DOCTOR).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Profil médecin actif requis."));}
 private List<TimeSlotDto> slots(Doctor d,LocalDate date,ZoneId zone){if(servicesFor(d).isEmpty())return List.of();LocalDate today=LocalDate.now(zone);if(date.isBefore(today)||date.isAfter(today.plusDays(maximumHorizonDays)))return List.of();List<Absence> dayAbsences=absences.findByDoctorIdAndStartDateLessThanEqualAndEndDateGreaterThanEqual(d.getId(),date,date);List<Availability> windows=availabilities.findByDoctorIdAndIsoWeekdayOrderByStartTimeAsc(d.getId(),date.getDayOfWeek().getValue());if(dayAbsences.stream().anyMatch(a->a.getStartTime()==null)||windows.isEmpty())return List.of();List<TimeSlotDto> out=new ArrayList<>();LocalDateTime earliest=LocalDateTime.now(zone).plusMinutes(minimumNoticeMinutes);for(Availability a:windows){String label=a.getWindowNumber()==2?"Deuxième plage":"Première plage";LocalDateTime cursor=date.atTime(a.getStartTime()),limit=date.atTime(a.getEndTime());while(!cursor.plusMinutes(a.getSlotDurationMinutes()).isAfter(limit)){LocalDateTime slotStart=cursor;LocalDateTime finish=slotStart.plusMinutes(a.getSlotDurationMinutes());boolean blocked=false;for(Absence absence:dayAbsences)if(absence.getStartTime()!=null&&slotStart.isBefore(date.atTime(absence.getEndTime()))&&finish.isAfter(date.atTime(absence.getStartTime()))){blocked=true;break;}if(!blocked&&!slotStart.isBefore(earliest)){Instant s=slotStart.atZone(zone).toInstant(),e=finish.atZone(zone).toInstant();out.add(new TimeSlotDto(s.toString(),s,e,"AVAILABLE",label));}cursor=finish.plusMinutes(a.getPauseMinutes());}}return out;}
 private List<TimeSlotDto> availableSlots(Doctor doctor,LocalDate date,ZoneId zone){List<TimeSlotDto> slots=slots(doctor,date,zone);if(slots.isEmpty())return slots;Instant from=date.atStartOfDay(zone).toInstant(),to=date.plusDays(1).atStartOfDay(zone).toInstant();List<Appointment> booked=appointments.findOverlapping(doctor.getId(),List.of(AppointmentStatus.PENDING,AppointmentStatus.CONFIRMED),from,to);return slots.stream().filter(slot->booked.stream().noneMatch(a->a.getStartAt().isBefore(slot.endsAt())&&a.getEndAt().isAfter(slot.startsAt()))).toList();}
 private List<MedicalServiceDto> services(Doctor d){return servicesFor(d);}
 public List<MedicalServiceDto> servicesFor(Doctor d){List<MedicalServiceDto> listed=parseServicePayload(d.getServicesJson());if(!listed.isEmpty())return listed;DoctorApplication application=d.getApplication();if(application!=null){List<MedicalServiceDto> source=parseServicePayload(application.getServicesJson());if(!source.isEmpty()){System.getLogger(getClass().getName()).log(System.Logger.Level.WARNING,"Profil médecin "+d.getId()+" : services_json vide/invalide; services récupérés depuis la candidature liée.");return source;}}return listed;}
 private List<MedicalServiceDto> parseServices(String raw,UUID id){List<MedicalServiceDto> listed=parseServicePayload(raw);if(listed.isEmpty()&&raw!=null&&!raw.isBlank()&&!raw.trim().equals("[]"))System.getLogger(getClass().getName()).log(System.Logger.Level.WARNING,"Candidature médecin "+id+" : services_json invalide ou incomplet; services ignorés.");return listed;}
 private List<MedicalServiceDto> parseServicePayload(String raw){if(raw==null||raw.isBlank())return List.of();try{com.fasterxml.jackson.databind.JsonNode root=json.readTree(raw);if(root.isTextual())root=json.readTree(root.asText());if(root!=null&&root.isObject()&&root.has("services"))root=root.get("services");if(root==null||root.isNull())return List.of();List<com.fasterxml.jackson.databind.JsonNode> items=new ArrayList<>();if(root.isArray())root.forEach(items::add);else if(root.isObject())items.add(root);else return List.of();List<MedicalServiceDto> result=new ArrayList<>();for(var item:items){String name=null,price=null;if(item.isTextual())name=item.asText();else if(item.isObject()){name=text(item,"name","serviceName","title","label","service");price=text(item,"price","tarif","cost");}if(name!=null&&!name.isBlank())result.add(new MedicalServiceDto(name.trim(),price==null?null:price.trim()));}return List.copyOf(result);}catch(Exception e){return List.of();}}
 private String text(com.fasterxml.jackson.databind.JsonNode node,String...keys){for(String key:keys){var value=node.get(key);if(value!=null&&!value.isNull()){String result=value.isTextual()?value.asText():value.isNumber()?value.asText():null;if(result!=null&&!result.isBlank())return result;}}return null;}
 private List<Integer> parseDays(DoctorApplication a){try{List<String> values=json.readValue(a.getWorkingDaysJson(),new TypeReference<>(){});return values.stream().map(v->v.equals("0")?7:Integer.parseInt(v)).filter(v->v>=1&&v<=7).distinct().toList();}catch(Exception e){System.getLogger(getClass().getName()).log(System.Logger.Level.WARNING,"Candidature médecin "+a.getId()+" : working_days_json invalide; disponibilités ignorées.",e);return List.of();}}
 private void warn(DoctorApplication a,String source){System.getLogger(getClass().getName()).log(System.Logger.Level.WARNING,"Candidature médecin "+a.getId()+" : données "+source+" absentes ou invalides; profil créé sans disponibilité.");}
 private String writeServices(List<MedicalServiceDto> list){try{return json.writeValueAsString(list);}catch(Exception e){return "[]";}}
 private boolean validDuration(int d){return d>=5&&d<=240;} private String safe(String s){return s==null?"":s;} private String blank(String s){return s==null||s.isBlank()?null:s.trim();} private String clean(String s){return s==null||s.isBlank()?null:s.trim();}
 private void validateUnique(UUID doctorId,UUID except,int day,LocalTime start,LocalTime end){List<Availability> sameDay=availabilities.findByDoctorIdAndIsoWeekdayOrderByStartTimeAsc(doctorId,day);for(Availability existing:sameDay){if(existing.getId()!=null&&existing.getId().equals(except))continue;if(start.isBefore(existing.getEndTime())&&end.isAfter(existing.getStartTime()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Cette plage chevauche une autre disponibilité du même jour.");}if(except==null&&sameDay.size()>=2)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Deux plages maximum sont autorisées par jour.");if(start.getMinute()%5!=0||end.getMinute()%5!=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Les heures doivent être réglées par pas de 5 minutes.");}
 private LocalTime parseTime(String s){try{return LocalTime.parse(s);}catch(Exception e){throw new IllegalArgumentException("Heure invalide : utilisez HH:mm.");}} private LocalTime parseSafeTime(String s){try{return s==null?null:LocalTime.parse(s);}catch(Exception e){return null;}}
 @Transactional(readOnly=true) public List<AvailabilityCalendarDayDto> calendar(UUID doctorId,YearMonth month){Doctor d=doctors.findByIdAndActiveTrue(doctorId).filter(x->x.getUser().getStatus().equals("ACTIVE")&&x.getUser().getRole()==UserRole.DOCTOR).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profil médecin introuvable."));LocalDate today=LocalDate.now(ZoneId.of("Africa/Tunis"));List<AvailabilityCalendarDayDto> out=new ArrayList<>();for(int i=1;i<=month.lengthOfMonth();i++){LocalDate date=month.atDay(i);List<Availability> windows=availabilities.findByDoctorIdAndIsoWeekdayOrderByStartTimeAsc(d.getId(),date.getDayOfWeek().getValue());List<Absence> dayAbsences=absences.findByDoctorIdAndStartDateLessThanEqualAndEndDateGreaterThanEqual(d.getId(),date,date);List<TimeSlotDto> available=availableSlots(d,date,ZoneId.of("Africa/Tunis"));boolean allWindowsAbsent=!windows.isEmpty()&&windows.stream().allMatch(w->dayAbsences.stream().anyMatch(a->a.getStartTime()==null||!a.getStartTime().isAfter(w.getStartTime())&&!a.getEndTime().isBefore(w.getEndTime())));String status=date.isBefore(today)?"PAST":allWindowsAbsent?"ABSENT":windows.isEmpty()?"DAY_OFF":!available.isEmpty()?"AVAILABLE":"FULL";out.add(new AvailabilityCalendarDayDto(date,status,available.size(),available.isEmpty()?null:available.get(0).startsAt()));}return out;}
 @Transactional(readOnly=true) public Instant nextAvailability(Doctor d,LocalDate from){ZoneId zone=ZoneId.of("Africa/Tunis");for(int i=0;i<=maximumHorizonDays;i++){List<TimeSlotDto> slots=availableSlots(d,from.plusDays(i),zone);if(!slots.isEmpty())return slots.get(0).startsAt();}return null;}
 @Transactional public List<AvailabilityDto> replaceWeeklyAvailability(String email,WeeklyAvailabilityRequest request){Doctor d=lockOwnSchedule(email);Map<Integer,List<WeeklyAvailabilityRequest.Window>> byDay=new HashMap<>();for(var w:request.windows()){LocalTime start=parseTime(w.startTime()),end=parseTime(w.endTime());if(start.getMinute()%5!=0||end.getMinute()%5!=0||start.getSecond()!=0||end.getSecond()!=0||!end.isAfter(start)||Duration.between(start,end).toMinutes()<request.slotDurationMinutes())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Chaque plage doit utiliser des pas de 5 minutes, finir après son début et contenir au moins un créneau.");byDay.computeIfAbsent(w.isoWeekday(),k->new ArrayList<>()).add(w);}for(var entry:byDay.entrySet()){var windows=entry.getValue();if(windows.size()>2||windows.stream().map(WeeklyAvailabilityRequest.Window::period).distinct().count()!=windows.size())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Deux plages maximum sont autorisées par jour, sans doublon.");var first=windows.stream().filter(w->w.period()==1).findFirst().orElse(null);var second=windows.stream().filter(w->w.period()==2).findFirst().orElse(null);if(first!=null&&second!=null&&!parseTime(second.startTime()).isAfter(parseTime(first.endTime())))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"La deuxième plage doit commencer après la fin de la première.");for(var w:windows)for(var other:windows)if(w!=other&&parseTime(w.startTime()).isBefore(parseTime(other.endTime()))&&parseTime(w.endTime()).isAfter(parseTime(other.startTime())))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Les plages d’un même jour ne peuvent pas se chevaucher.");}availabilities.deleteByDoctorId(d.getId());List<Availability> saved=new ArrayList<>();for(var entry:byDay.entrySet())for(var window:entry.getValue())saved.add(availabilities.save(new Availability(d,entry.getKey(),window.period(),parseTime(window.startTime()),parseTime(window.endTime()),request.slotDurationMinutes(),request.pauseMinutes())));d.updateProfile(d.getServiceTitle(),d.getCity(),d.getAddress(),d.getLocation(),d.getDescription(),request.slotDurationMinutes(),request.pauseMinutes(),d.getServicesJson());return saved.stream().map(AvailabilityDto::from).toList();}
}
